// Generated by diff_geometry({ render: true }). Added material is green,
// removed material is red, material present on both sides is a translucent
// ghost. Re-runnable: kernelcad render inspect <this file> <outDir>.
const common_root = await lib.fromBREP('./common-root.brep');
const removed_root = await lib.fromBREP('./removed-root.brep');
const overlay = assembly('diff-overlay');
overlay.part('common_root', common_root.material({ baseColor: '#b8bcc0', roughness: 0.6, opacity: 0.22 }));
overlay.part('removed_root', removed_root.finish('paint-matte', { color: '#e74c3c' }));
return overlay.model();
